import { t } from "../../i18n/index.ts";
import { registerBrowserEnglish } from "../../i18n/locales/en-browser.ts";
import type { AnnotationStroke } from "./browser-annotation.ts";
import type {
  BrowserInspectedNode,
  BrowserOperatorInput,
  BrowserRequestClient,
} from "./browser-client.ts";
import {
  clickBrowserCoords,
  inspectBrowserElementAt,
  insertBrowserText,
  isBrowserEvaluateDisabledError,
  isBrowserOperatorInputUnsupportedError,
  pressBrowserKey,
  scrollBrowserBy,
  sendBrowserOperatorInput,
} from "./browser-client.ts";
import type { BrowserPanelOperations } from "./browser-panel-operation-ownership.ts";
import type { BrowserPanelPendingInput } from "./browser-panel-pending-input.ts";
import type { BrowserPanelStateWriter } from "./browser-panel-state.ts";
import type { BrowserPanelStream } from "./browser-panel-stream.ts";
import {
  browserPanelInspectHighlightRegion,
  browserPanelNormalizedPoint,
  browserPanelRemotePoint,
  browserPanelShouldForwardKey,
  dispatchCompositedBrowserAnnotation,
  paintBrowserPanelOverlay,
} from "./browser-panel-surface.ts";

registerBrowserEnglish();

const INSPECT_THROTTLE_MS = 120;
const STREAM_WHEEL_INTERVAL_MS = 50;
const SNAPSHOT_WHEEL_INTERVAL_MS = 150;
// Matches the browser route's per-request input bound.
const MAX_INPUT_BURST = 100;

type QueuedInput = { input: BrowserOperatorInput; targetId: string };

interface BrowserPanelInputHost extends BrowserPanelStateWriter<
  | "mode"
  | "strokes"
  | "view"
  | "tabs"
  | "activeTargetId"
  | "inspected"
  | "inspectPointer"
  | "evaluateUnavailable"
  | "errorText"
  | "noticeText"
> {
  readonly stream: Pick<BrowserPanelStream, "ownsView">;
  readonly operations: Pick<
    BrowserPanelOperations,
    "beginInspection" | "captureClient" | "epoch" | "isLive"
  >;
  readonly pendingInput: Pick<
    BrowserPanelPendingInput,
    "clearInput" | "queueInspection" | "queueWheel"
  >;
  runAction(
    action: (client: BrowserRequestClient) => Promise<void>,
    refreshView?: boolean,
  ): Promise<boolean>;
  reportError(error: unknown): void;
  exitCaptureModes(): void;
}

type BrowserPanelDrawingGesture = {
  pointerId: number;
  captureTarget: HTMLElement;
  stroke: AnnotationStroke;
};

/** Owns pointer, keyboard, annotation, and inspection input for the browser surface. */
export class BrowserPanelInputOwner {
  elements: {
    stage?: HTMLElement;
    viewport?: HTMLElement;
    input?: HTMLTextAreaElement;
    overlay?: HTMLCanvasElement;
  } = {};
  // An annotation stroke belongs to one pointer until that owner or the panel lifecycle ends.
  private drawingGesture: BrowserPanelDrawingGesture | null = null;
  private suppressStageClick = false;
  private inspectionError: string | null = null;
  private clickSequence = 0;
  private inputGeneration = 0;
  // Clicks, keys and text leave in input order. While one burst is in flight the
  // next inputs queue, so a typing burst shares one navigation guard on the Gateway.
  private queuedInputs: QueuedInput[] = [];
  private inputFlight: Promise<void> | null = null;
  // The browser route bound to this client answered that it has no operator input.
  private operatorInputUnsupportedClient: BrowserRequestClient | null = null;
  // After a failed click the previous field may still be focused; text waits for a new click.
  private focusUncertain = false;
  private compositionCurrent: (() => boolean) | null = null;
  private scrollPoint: { x: number; y: number } | null = null;
  private touchScroll: {
    pointerId: number;
    startX: number;
    startY: number;
    point: { x: number; y: number };
    scrolling: boolean;
    current: () => boolean;
  } | null = null;

  constructor(private readonly host: BrowserPanelInputHost) {}

  resetCaptureState(): void {
    this.host.pendingInput.clearInput();
    this.cancelOverlayPointerGesture();
    this.queuedInputs = [];
    this.inputFlight = null;
    this.focusUncertain = false;
    this.compositionCurrent = null;
    this.touchScroll = null;
    const input = this.elements.input;
    if (input) {
      input.value = "";
      input.blur();
    }
    this.clickSequence += 1;
    this.inputGeneration += 1;
  }

  private remotePoint(event: MouseEvent): { x: number; y: number } | null {
    return browserPanelRemotePoint(this.elements.stage ?? null, event, this.host.view);
  }

  inspectHighlightRegion() {
    return browserPanelInspectHighlightRegion(this.host.view, this.host.inspected);
  }

  handleStageClick(event: MouseEvent): void {
    if (this.suppressStageClick) {
      // Inspect capture and touch scrolling must not also click the remote page.
      this.suppressStageClick = false;
      return;
    }
    if (this.host.mode !== "interact") {
      return;
    }
    // The empty input gives WebKit native Paste commands for the remote page.
    this.elements.input?.focus({ preventScroll: true });
    const point = this.remotePoint(event);
    if (!point) {
      return;
    }
    this.clickSequence += 1;
    this.queueInput({ kind: "clickCoords", x: point.x, y: point.y }, false);
  }

  handleWheel(event: WheelEvent): void {
    if (this.queueScroll(event.deltaX, event.deltaY, this.remotePoint(event))) {
      event.preventDefault();
    }
  }

  private queueScroll(
    horizontal: number,
    vertical: number,
    point: { x: number; y: number } | null,
  ): boolean {
    if (this.host.mode !== "interact" || !this.host.view) {
      return false;
    }
    const client = this.host.operations.captureClient();
    const targetId = this.host.activeTargetId;
    if (!client || !targetId || this.host.view.targetId !== targetId) {
      return false;
    }
    // Coalesced deltas scroll whatever sits under the pointer when they flush.
    this.scrollPoint = point;
    const epoch = this.host.operations.epoch;
    // Match the live stream's frame cadence; screenshot fallback keeps its lower request rate.
    const interval = this.host.stream.ownsView(targetId)
      ? STREAM_WHEEL_INTERVAL_MS
      : SNAPSHOT_WHEEL_INTERVAL_MS;
    this.host.pendingInput.queueWheel(horizontal, vertical, interval, (deltaX, deltaY) => {
      if (
        !this.host.operations.isLive(epoch, client) ||
        this.host.activeTargetId !== targetId ||
        this.host.view?.targetId !== targetId ||
        this.host.mode !== "interact"
      ) {
        return;
      }
      const scrollPoint = this.scrollPoint;
      void this.host.runAction(async (actionClient) => {
        if (this.host.evaluateUnavailable) {
          // No page JS allowed: fall back to a coarse keyboard scroll.
          await pressBrowserKey(actionClient, {
            targetId,
            key: deltaY >= 0 ? "PageDown" : "PageUp",
          });
          return;
        }
        await scrollBrowserBy(actionClient, {
          targetId,
          deltaX,
          deltaY,
          ...(scrollPoint ? { point: scrollPoint } : {}),
        });
      });
    });
    return true;
  }

  private captureInputCurrent(): () => boolean {
    const client = this.host.operations.captureClient();
    const targetId = this.host.activeTargetId;
    const epoch = this.host.operations.epoch;
    const generation = this.inputGeneration;
    const clickSequence = this.clickSequence;
    return () =>
      Boolean(
        client &&
        targetId &&
        this.host.operations.isLive(epoch, client) &&
        this.host.activeTargetId === targetId &&
        this.host.view?.targetId === targetId &&
        this.inputGeneration === generation &&
        this.clickSequence === clickSequence &&
        this.host.mode === "interact",
      );
  }

  handleTouchPointerDown(event: PointerEvent): void {
    if (this.touchScroll) {
      return;
    }
    this.suppressStageClick = false;
    // Pen contact drags scroll like fingers; mouse drags stay clicks and wheel scrolls.
    if (
      (event.pointerType !== "touch" && event.pointerType !== "pen") ||
      this.host.mode !== "interact"
    ) {
      return;
    }
    const point = this.remotePoint(event);
    const current = this.captureInputCurrent();
    if (point && current()) {
      this.touchScroll = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        point,
        scrolling: false,
        current,
      };
    }
  }

  handleTouchPointerMove(event: PointerEvent): void {
    const gesture = this.touchScroll;
    if (!gesture || gesture.pointerId !== event.pointerId || !gesture.current()) {
      return;
    }
    if (
      !gesture.scrolling &&
      Math.hypot(event.clientX - gesture.startX, event.clientY - gesture.startY) < 8
    ) {
      return;
    }
    const point = this.remotePoint(event);
    if (!point) {
      return;
    }
    event.preventDefault();
    gesture.scrolling = true;
    this.suppressStageClick = true;
    this.queueScroll(gesture.point.x - point.x, gesture.point.y - point.y, point);
    gesture.point = point;
  }

  handleTouchPointerEnd(event: PointerEvent): void {
    if (this.touchScroll?.pointerId === event.pointerId) {
      this.touchScroll = null;
    }
  }

  handleCompositionStart(): void {
    this.compositionCurrent = this.captureInputCurrent();
  }

  handleCompositionEnd(event: CompositionEvent): void {
    const current = this.compositionCurrent;
    this.compositionCurrent = null;
    if (current?.() && event.data) {
      this.queueInput({ kind: "insertText", text: event.data });
    }
    if (event.currentTarget instanceof HTMLTextAreaElement) {
      event.currentTarget.value = "";
    }
  }

  handleTextInput(event: InputEvent): void {
    // Let the IME own its local composition; only its final text goes to the remote field.
    if (event.isComposing || this.compositionCurrent) {
      return;
    }
    if (event.type === "beforeinput" && !event.cancelable) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    const input = event.currentTarget;
    const text = event.data ?? (input instanceof HTMLTextAreaElement ? input.value : "");
    if (event.inputType === "insertReplacementText") {
      // The empty proxy cannot identify the remote range a local correction would replace.
      this.host.setState("noticeText", t("browser.manualTextCorrection"));
    } else if (["insertText", "insertFromPaste"].includes(event.inputType) && text) {
      this.queueInput({ kind: "insertText", text });
    } else {
      const key =
        event.inputType === "deleteContentBackward"
          ? "Backspace"
          : event.inputType === "deleteContentForward"
            ? "Delete"
            : event.inputType === "insertLineBreak" || event.inputType === "insertParagraph"
              ? "Enter"
              : null;
      if (key) {
        this.queueInput({ kind: "press", key });
      }
    }
    // insertFromComposition follows compositionend on WebKit; the end event already sent it.
    if (input instanceof HTMLTextAreaElement) {
      input.value = "";
    }
  }

  handleViewportKeydown(event: KeyboardEvent): void {
    if (this.host.mode !== "interact" || !this.host.view) {
      return;
    }
    if (
      event.isComposing ||
      event.keyCode === 229 ||
      this.compositionCurrent ||
      event.metaKey ||
      event.ctrlKey ||
      event.altKey
    ) {
      return;
    }
    const key = event.key;
    if (!browserPanelShouldForwardKey(key)) {
      return;
    }
    event.preventDefault();
    this.queueInput({ kind: "press", key });
  }

  handleViewportPaste(event: ClipboardEvent): void {
    // Clipboard bytes belong to the remote field, never the local textarea or chat.
    event.preventDefault();
    event.stopPropagation();
    if (!event.clipboardData?.types.includes("text/plain")) {
      return;
    }
    const text = event.clipboardData.getData("text/plain");
    if (text) {
      this.queueInput({ kind: "insertText", text });
    }
  }

  private queueInput(input: BrowserOperatorInput, requireView = true): void {
    const targetId = this.host.activeTargetId;
    if (
      !this.host.operations.captureClient() ||
      !targetId ||
      (requireView && this.host.view?.targetId !== targetId) ||
      this.host.mode !== "interact"
    ) {
      return;
    }
    if (input.kind === "clickCoords") {
      this.focusUncertain = false;
    } else if (this.focusUncertain) {
      return;
    }
    this.queuedInputs.push({ input, targetId });
    if (!this.inputFlight) {
      const flight = this.flushInputs(this.inputGeneration);
      this.inputFlight = flight;
      void flight.finally(() => {
        if (this.inputFlight === flight) {
          this.inputFlight = null;
        }
      });
    }
  }

  private async flushInputs(generation: number): Promise<void> {
    while (this.inputGeneration === generation && this.queuedInputs.length > 0) {
      const client = this.host.operations.captureClient();
      const targetId = this.host.activeTargetId;
      if (!client || !targetId || this.host.mode !== "interact") {
        this.queuedInputs = [];
        return;
      }
      // Input aimed at another tab never follows the selection to this one.
      this.queuedInputs = this.queuedInputs.filter((entry) => entry.targetId === targetId);
      const inputs = this.queuedInputs.splice(0, MAX_INPUT_BURST).map((entry) => entry.input);
      if (inputs.length === 0) {
        return;
      }
      const epoch = this.host.operations.epoch;
      const current = () =>
        this.inputGeneration === generation &&
        this.host.operations.isLive(epoch, client) &&
        this.host.activeTargetId === targetId &&
        this.host.mode === "interact";
      let outcome = { navigated: false, blockedByDialog: false, unsent: 0 };
      const delivered = await this.host.runAction(async (actionClient) => {
        outcome = await this.sendInputs(actionClient, targetId, inputs, current);
      });
      if (this.inputGeneration !== generation || !this.host.operations.isLive(epoch, client)) {
        return;
      }
      const isClick = (input: BrowserOperatorInput) => input.kind === "clickCoords";
      const sentCount = inputs.length - outcome.unsent;
      const clicked = inputs.slice(0, sentCount).some(isClick);
      if (outcome.blockedByDialog) {
        // A page dialog stopped the burst. Input it withheld or that queued behind it
        // was typed for a page the dialog now blocks; a dropped click never moved focus.
        const droppedClick =
          inputs.slice(sentCount).some(isClick) ||
          this.queuedInputs.some((entry) => isClick(entry.input));
        this.queuedInputs = [];
        if (droppedClick) {
          this.focusUncertain = true;
        } else if (clicked) {
          this.focusUncertain = false;
        }
        this.host.setState("noticeText", t("browser.inputBlockedByDialog"));
      } else if (outcome.navigated) {
        // Input withheld from this burst or queued meanwhile was aimed at the document
        // the user saw before it changed.
        if (outcome.unsent > 0 || this.queuedInputs.length > 0) {
          this.queuedInputs = [];
          this.host.setState("noticeText", t("browser.inputDroppedAfterNavigation"));
        }
      } else if (delivered) {
        // A click that reached the page retargets focus after an earlier failed click.
        if (clicked) {
          this.focusUncertain = false;
        }
      } else {
        // A failed click can leave the previous field focused; only a new click retargets.
        const nextClick = this.queuedInputs.findIndex(
          (entry) => entry.input.kind === "clickCoords",
        );
        this.queuedInputs = nextClick < 0 ? [] : this.queuedInputs.slice(nextClick);
        if (clicked && nextClick < 0) {
          this.focusUncertain = true;
        }
      }
    }
  }

  /** Reports whether a navigation withheld input from the next document, and how much. */
  private async sendInputs(
    client: BrowserRequestClient,
    targetId: string,
    inputs: BrowserOperatorInput[],
    current: () => boolean,
  ): Promise<{ navigated: boolean; blockedByDialog: boolean; unsent: number }> {
    if (this.operatorInputUnsupportedClient !== client) {
      try {
        const result = await sendBrowserOperatorInput(client, { targetId, inputs });
        return {
          navigated: result.navigated,
          blockedByDialog: result.blockedByDialog,
          unsent: inputs.length - result.sent,
        };
      } catch (error) {
        if (!isBrowserOperatorInputUnsupportedError(error)) {
          throw error;
        }
        this.operatorInputUnsupportedClient = client;
      }
    }
    // Profiles without operator input: one guarded act per input, each
    // only while the panel still owns this input.
    for (const input of inputs) {
      if (!current()) {
        break;
      }
      if (input.kind === "clickCoords") {
        await clickBrowserCoords(client, { targetId, x: input.x, y: input.y });
      } else if (input.kind === "press") {
        await pressBrowserKey(client, { targetId, key: input.key });
      } else {
        await insertBrowserText(client, { targetId, text: input.text });
      }
    }
    return { navigated: false, blockedByDialog: false, unsent: 0 };
  }

  handleOverlayPointerDown(event: PointerEvent): void {
    if (this.host.mode === "inspect") {
      this.suppressStageClick = true;
      void this.sendAnnotation({ element: this.host.inspected });
      return;
    }
    if (this.host.mode !== "annotate" || event.button !== 0 || this.drawingGesture) {
      return;
    }
    const point = browserPanelNormalizedPoint(this.elements.stage ?? null, event);
    if (!point) {
      return;
    }
    const captureTarget =
      event.currentTarget instanceof HTMLElement
        ? event.currentTarget
        : event.target instanceof HTMLElement
          ? event.target
          : null;
    if (!captureTarget) {
      return;
    }
    event.preventDefault();
    try {
      captureTarget.setPointerCapture(event.pointerId);
    } catch {
      // Detached and synthetic targets can reject capture; owner filtering still applies.
    }
    const gesture = {
      pointerId: event.pointerId,
      captureTarget,
      stroke: { points: [point] },
    };
    this.drawingGesture = gesture;
    this.host.setState("strokes", [...this.host.strokes, gesture.stroke]);
    this.paintOverlay();
  }

  handleOverlayPointerMove(event: PointerEvent): void {
    if (this.host.mode === "annotate") {
      const gesture = this.drawingGesture;
      if (!gesture || event.pointerId !== gesture.pointerId) {
        return;
      }
      const point = browserPanelNormalizedPoint(this.elements.stage ?? null, event);
      if (point) {
        gesture.stroke.points.push(point);
        this.paintOverlay();
      }
      return;
    }
    if (this.host.mode === "inspect") {
      const client = this.host.operations.captureClient();
      const point = this.remotePoint(event);
      const stagePoint = browserPanelNormalizedPoint(this.elements.stage ?? null, event);
      const targetId = this.host.activeTargetId;
      if (!client || !point || !stagePoint || !targetId || this.host.evaluateUnavailable) {
        return;
      }
      const current = this.host.operations.beginInspection(
        client,
        () =>
          this.host.activeTargetId === targetId &&
          this.host.view?.targetId === targetId &&
          this.host.mode === "inspect",
      );
      this.host.setState("inspected", null);
      this.host.setState("inspectPointer", stagePoint);
      this.paintOverlay();
      this.host.pendingInput.queueInspection(INSPECT_THROTTLE_MS, current, () => {
        void inspectBrowserElementAt(client, { targetId, x: point.x, y: point.y })
          .then((node) => {
            if (current()) {
              if (this.inspectionError !== null && this.host.errorText === this.inspectionError) {
                this.host.setState("errorText", null);
              }
              this.inspectionError = null;
              this.host.setState("inspected", node);
              this.paintOverlay();
            }
          })
          .catch((error: unknown) => {
            if (!current()) {
              return;
            }
            if (isBrowserEvaluateDisabledError(error)) {
              this.host.setState("evaluateUnavailable", true);
              this.host.setState("errorText", t("browser.inspectUnavailable"));
              this.host.setState("mode", "interact");
              return;
            }
            this.host.reportError(error);
            this.inspectionError = this.host.errorText;
          });
      });
    }
  }

  handleOverlayPointerUp(event: PointerEvent): void {
    if (event.pointerId === this.drawingGesture?.pointerId) {
      this.drawingGesture = null;
    }
  }

  cancelOverlayPointerGesture(): void {
    const gesture = this.drawingGesture;
    this.drawingGesture = null;
    if (!gesture) {
      return;
    }
    try {
      if (gesture.captureTarget.hasPointerCapture(gesture.pointerId)) {
        gesture.captureTarget.releasePointerCapture(gesture.pointerId);
      }
    } catch {
      // Capture may already be gone because its canvas was detached.
    }
  }

  undoStroke(): void {
    this.cancelOverlayPointerGesture();
    this.host.setState("strokes", this.host.strokes.slice(0, -1));
    this.paintOverlay();
  }

  clearStrokes(): void {
    this.cancelOverlayPointerGesture();
    this.host.setState("strokes", []);
    this.paintOverlay();
  }

  async sendAnnotation(params: { element?: BrowserInspectedNode | null }): Promise<void> {
    this.cancelOverlayPointerGesture();
    const view = this.host.view;
    const tab = this.host.tabs.find((entry) => entry.id === this.host.activeTargetId);
    const element = params.element ?? null;
    if (!view || (this.host.strokes.length === 0 && !element)) {
      return;
    }
    const highlight = element ? this.inspectHighlightRegion() : null;
    let result: ReturnType<typeof dispatchCompositedBrowserAnnotation>;
    try {
      result = dispatchCompositedBrowserAnnotation(
        view,
        tab,
        this.host.strokes,
        element,
        highlight,
      );
    } catch (error) {
      this.host.reportError(error);
      return;
    }
    if (result !== "accepted") {
      this.host.setState("noticeText", null);
      this.host.setState(
        "errorText",
        t(result === "unhandled" ? "browser.noChatTarget" : "browser.annotationLimitReached"),
      );
      return;
    }
    this.host.setState("errorText", null);
    this.host.setState("noticeText", t("browser.annotationSent"));
    this.host.exitCaptureModes();
  }

  /** Repaints the live stroke/highlight overlay; cheap, runs after render. */
  paintOverlay(): void {
    paintBrowserPanelOverlay(
      this.elements.overlay ?? null,
      this.elements.stage ?? null,
      this.host.strokes,
      this.host.mode === "inspect" ? this.inspectHighlightRegion() : null,
    );
  }
}
